  items=inv.get('invoices',inv)
else:
  items=inv
print('type', type(inv), 'n', len(items) if hasattr(items,'__len__') else '?')
# find recent
for i in items:
  vin=str(i.get('vendor_invoice_number') or i.get('invoice_number') or '')
  iid=str(i.get('invoice_id') or i.get('id') or '')
  if 'INBOX' in vin or iid.startswith('ING') or 'SLK' in vin or 'FIG' in vin or 'OD-' in vin or 'DD-' in vin or 'NIM' in vin or 'ACM-2026' in vin:
